#include "test_signing.h"
#include <cstdio>
#include <cstdlib>
using namespace druta::ui;
#define CHECK(x) do{if(!(x)){std::fprintf(stderr,"%d: %s\n",__LINE__,#x);std::abort();}}while(false)
int main(){const auto enable=test_signing_recipe(true),disable=test_signing_recipe(false);CHECK(enable.size()==3&&disable.size()==3&&enable[0].arguments[2]==L"DISABLE_INTEGRITY_CHECKS"&&enable[2].arguments[1]==L"TESTSIGNING"&&enable[2].arguments[2]==L"ON"&&disable[0].arguments[0]==L"/deletevalue"&&disable[2].arguments[2]==L"OFF");int probes=0,runs=0;TestSigningStatus status;status.secure_boot=false;status.administrator=true;status.bitlocker_protected=std::string("C:");TestSigningApi api;api.probe=[&]{++probes;return status;};api.run=[&](const TestSigningCommand&,uint32_t timeout){CHECK(timeout==30000);++runs;TestSigningProcessResult r;r.launched=true;r.output="captured";return r;};CHECK(read_test_signing_status(api).bitlocker_protected=="C:"&&probes==1&&runs==0);status.secure_boot=true;auto refused=execute_test_signing(true,api);CHECK(refused.refused&&!refused.may_have_changed&&runs==0&&probes==2);status.secure_boot=false;status.administrator=false;CHECK(execute_test_signing(true,api).refused&&runs==0);status.administrator.reset();CHECK(execute_test_signing(true,api).refused&&runs==0);status.administrator=true;status.secure_boot.reset();auto ok=execute_test_signing(true,api);CHECK(ok.ok&&ok.may_have_changed&&ok.commands.size()==3&&runs==3&&ok.commands[0].process.output=="captured"&&!ok.status.secure_boot);
 runs=0;api.run=[&](const TestSigningCommand&,uint32_t){TestSigningProcessResult r;r.launched=true;r.exit_code=++runs==2?5:0;r.output="details";return r;};auto partial=execute_test_signing(false,api);CHECK(!partial.ok&&partial.may_have_changed&&partial.commands.size()==3&&partial.commands[0].ok&&!partial.commands[1].ok&&partial.commands[2].ok&&runs==3);runs=0;api.run=[&](const TestSigningCommand&,uint32_t){++runs;TestSigningProcessResult r;r.launched=true;r.timed_out=true;return r;};auto timeout=execute_test_signing(true,api);CHECK(!timeout.ok&&timeout.may_have_changed&&timeout.commands.size()==3&&timeout.commands[0].process.timed_out);std::puts("Test signing explicit actions passed");}
